<!doctype html>
<html><head><meta charset="utf-8"><style>
@page{size:A4;margin:14mm}body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:10px}h1{font-size:22px;margin:0}.muted{color:#667085}.header{border-bottom:2px solid #172033;padding-bottom:14px;margin-bottom:18px}.grid{width:100%;margin:12px 0}.grid td{padding:4px 0}table.items{width:100%;border-collapse:collapse;margin-top:18px}table.items thead{display:table-header-group}table.items th,table.items td{border:1px solid #d0d5dd;padding:6px;text-align:right;word-break:break-word}table.items th:first-child,table.items td:first-child{text-align:left}.totals{margin-left:auto;width:45%;margin-top:18px}.totals td{padding:5px}.net{font-weight:bold;border-top:2px solid #172033}.footer{margin-top:35px;border-top:1px solid #d0d5dd;padding-top:10px}@media print{body{background:#fff}.no-print{display:none!important}tr{page-break-inside:avoid}}
</style></head><body>
<div class="header"><h1>MAKETO - Payout Statement</h1><div class="muted">{{ $payout->payout_number }} | Generated {{ now()->format('Y-m-d H:i T') }}</div></div>
<table class="grid"><tr><td><strong>Recipient</strong><br>{{ $recipientName }} ({{ ucfirst($payout->recipient_type) }} #{{ $payout->recipient_id }})</td><td><strong>Period</strong><br>{{ $payout->period_start->format('Y-m-d') }} to {{ $payout->period_end->format('Y-m-d') }}</td><td><strong>Status</strong><br>{{ strtoupper($payout->status) }}</td></tr></table>
<table class="items"><thead><tr><th>Reference</th><th>Date</th><th>Gross / Fee</th><th>Rate</th><th>Commission</th><th>Taken</th><th>Adjust.</th><th>Net</th></tr></thead><tbody>@foreach($payout->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->created_at?->format('Y-m-d') }}</td><td>{{ $payout->currency }} {{ $item->gross_amount }}</td><td>{{ $item->commissionEntry?->percentage_rate !== null ? $item->commissionEntry->percentage_rate.'%' : $item->commissionEntry?->calculation_type }}</td><td>{{ $payout->currency }} {{ $item->commission_amount }}<br>{{ strtoupper($item->commissionEntry?->status ?? 'N/A') }}</td><td>{{ $item->commissionEntry?->commission_taken ? 'YES' : 'NO' }}<br>{{ $item->commissionEntry?->taken_at?->format('Y-m-d H:i') ?: '-' }}</td><td>{{ $payout->currency }} {{ $item->adjustment_amount }}</td><td>{{ $payout->currency }} {{ $item->net_amount }}</td></tr>@endforeach</tbody></table>
<table class="totals"><tr><td>Gross</td><td>{{ $payout->currency }} {{ $payout->gross_amount }}</td></tr><tr><td>Platform commission</td><td>{{ $payout->currency }} {{ $payout->commission_amount }}</td></tr><tr><td>Adjustments</td><td>{{ $payout->currency }} {{ $payout->adjustment_amount }}</td></tr><tr class="net"><td>Net payout</td><td>{{ $payout->currency }} {{ $payout->net_amount }}</td></tr></table>
<div class="footer"><strong>Payment:</strong> {{ $payout->payment_method ?: 'Pending' }} | {{ $payout->payment_reference ?: 'No reference' }} | Paid {{ $payout->paid_at?->format('Y-m-d H:i T') ?: '-' }}<br><strong>Approved by:</strong> {{ $payout->approver?->display_name ?: '-' }} | {{ $payout->approved_at?->format('Y-m-d H:i T') ?: '-' }}<br><span class="muted">Generated by Marketo | {{ now()->format('Y-m-d H:i:s T') }} | {{ $payout->payout_number }}. This statement comes from immutable payout items and the versioned commission ledger.</span></div>
</body></html>
